func validateDeployFlags(o *Options) error {
	if o.Deploy.DryRun && o.Deploy.Reconfigure {
		return fmt.Errorf(
			"--dry-run cannot be combined with --reconfigure: " +
				"reconfigure always destroys and redeploys the full lab",
